import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Access","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/access.md","filePath":"03-developer/models/access.md"}`),a={name:`03-developer/models/access.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to “Access”">​</a></h1><p>Model reference · <code>App\\Models\\Access</code></p><h3 id="_1-model" tabindex="-1">1. Model <a class="header-anchor" href="#_1-model" aria-label="Permalink to “1. Model”">​</a></h3><p>The user access model in the ACL (Access Control List) system. This model defines which sections or operations of the system each user can access.</p><p>Access is controlled based on Route names. In addition to restricting requests through the ACL Middleware, this model is also used to determine whether site menus are displayed.</p><p>The system divides users into three main levels:</p><ul><li><strong>Developer:</strong> Full access to the system, including sensitive and administrative sections.</li><li><strong>Admin:</strong> Broad administrative access, but without access to some critical and sensitive parts of the system, such as changing the site&#39;s Theme or defining a new language.</li><li><strong>User:</strong> A regular user whose permitted access is determined by an administrator.</li></ul><p>This classification represents the system&#39;s overall logic; details about the roles and their restrictions are explained in the <a href="./user.html">User</a> model documentation.</p><h3 id="_2-table-accesses" tabindex="-1">2. Table: <code>accesses</code> <a class="header-anchor" href="#_2-table-accesses" aria-label="Permalink to “2. Table: accesses”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Comment</th></tr></thead><tbody><tr><td><code>id</code></td><td>bigint unsigned</td><td>No</td><td>Access record identifier</td></tr><tr><td><code>user_id</code></td><td>bigint unsigned</td><td>No</td><td>User identifier</td></tr><tr><td><code>route</code></td><td>varchar(255)</td><td>No</td><td>Route name the user is permitted to access</td></tr><tr><td><code>owner</code></td><td>tinyint(1)</td><td>No</td><td>Restricts access to resources owned by the user; not yet complete</td></tr><tr><td><code>created_at</code></td><td>timestamp</td><td>Yes</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>timestamp</td><td>Yes</td><td>Last edit time</td></tr></tbody></table><h3 id="_3-extra-description-of-table-fields" tabindex="-1">3. Extra description of table fields <a class="header-anchor" href="#_3-extra-description-of-table-fields" aria-label="Permalink to “3. Extra description of table fields”">​</a></h3><p><strong><code>accesses.user_id</code></strong></p><p>Specifies which user this permission belongs to and references the <code>users</code> table.</p><p>Related model documentation: <a href="./user.html">User</a>.</p><p><strong><code>accesses.route</code></strong></p><p>Stores the Route name the user is permitted to access. The value of this field must match a Route name in the Laravel system.</p><p>For example:</p><ul><li><code>admin.product.index</code></li><li><code>admin.product.create</code></li></ul><p>When checking a request, the ACL Middleware checks the Route name to determine whether a regular user is allowed to access it.</p><p>This information is also used to determine which menus should be displayed to the user. Therefore, in addition to controlling requests, the ACL also helps build a user interface tailored to the user&#39;s permissions.</p><p><strong><code>accesses.owner</code></strong></p><p>This field is intended to support resource ownership-based access restrictions, but it has not yet been implemented or completed and should not currently be considered an active, reliable feature.</p><p>The design goal is that, when enabled, users can only view or edit resources they own. For example, they could view or modify their own posts but would not have access to other users&#39; posts.</p><h3 id="_4-methods" tabindex="-1">4. Methods <a class="header-anchor" href="#_4-methods" aria-label="Permalink to “4. Methods”">​</a></h3><p>This model has no custom methods defined.</p>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};